import {test} from 'node:test';import assert from 'node:assert/strict';import fs from 'node:fs';import os from 'node:os';import path from 'node:path';import {inspectOutput} from './check-production-contract.mjs';
function fixture(t){const dir=fs.mkdtempSync(path.join(os.tmpdir(),'profile-contract-'));t.after(()=>fs.rmSync(dir,{recursive:true,force:true}));fs.writeFileSync(path.join(dir,'main.js'),'console.log(1);\n//# sourceMappingURL=main.js.map\n');fs.writeFileSync(path.join(dir,'main.css'),'body{color:red}');fs.writeFileSync(path.join(dir,'main.js.map'),JSON.stringify({version:3,sources:['../src/main.tsx'],sourcesContent:['console.log(1);'],names:[],mappings:'AAAA'}));return dir;}
test('accepts ES2022 output with a usable original source mapping',async t=>assert.equal((await inspectOutput(fixture(t))).passed,true));
test('rejects source maps that exist but contain no mappings',async t=>{const d=fixture(t),p=path.join(d,'main.js.map'),m=JSON.parse(fs.readFileSync(p));m.mappings='';fs.writeFileSync(p,JSON.stringify(m));assert.equal((await inspectOutput(d)).passed,false);});
test('rejects mapped sources without embedded original content',async t=>{const d=fixture(t),p=path.join(d,'main.js.map'),m=JSON.parse(fs.readFileSync(p));m.sourcesContent=[null];fs.writeFileSync(p,JSON.stringify(m));assert.equal((await inspectOutput(d)).passed,false);});
test('rejects newer-than-ES2022 syntax',async t=>{const d=fixture(t);fs.writeFileSync(path.join(d,'main.js'),'using resource = open();\n//# sourceMappingURL=main.js.map');assert.equal((await inspectOutput(d)).passed,false);});
test('rejects source maps outside the output directory',async t=>{const d=fixture(t);fs.writeFileSync(path.join(d,'main.js'),'console.log(1);\n//# sourceMappingURL=../outside.map');assert.equal((await inspectOutput(d)).passed,false);});
test('accepts root-relative source-map URLs served from dist',async t=>{const d=fixture(t);fs.writeFileSync(path.join(d,'main.js'),'console.log(1);\n//# sourceMappingURL=/main.js.map');assert.equal((await inspectOutput(d)).passed,true);});
